def main():
    stem = 'abjuration_conjuration_rank6'
    draft = A / 'ABJURATION_CONJURATION_RANK6_OPERATING_PROPOSALS.json'
    out = R / f'data/director/spell_proposals/{stem}.json'
    doc = R / 'docs/spells/proposals/ABJURATION_CONJURATION_RANK6.md'
    receipt = A / 'ABJURATION_CONJURATION_RANK6_OPERATING_PROPOSAL_CHECK.json'
    assert not any(p.exists() for p in [draft, out, doc, receipt]), 'One-use authoring: preserve prior outputs'
    prep_path = A / 'ABJURATION_CONJURATION_RANK6_SOURCE_PREPARATION.json'
    prep = read(prep_path)
    selected = {s['spellId']: s for s in prep['selectedSpells'] if s['scope'] == 'pre-push mechanical source question'}
    deferred = [s for s in prep['selectedSpells'] if s['scope'] == 'post-push receipt only']
    cat_path = R / 'data/public/spell_playtests/catalog.json'
    idx_path = cat_path.with_name('authored_review_index.json')
    core_path = R / 'data/public/Decennium_Descent_Core_Systems_Data_v2_Known_Descent.json'
    cat, idx, core = read(cat_path), read(idx_path), read(core_path)
    catalog = {x['id']: x for x in cat['spells']}
    entries = {x['id']: x for x in idx['entries']}
    inputs = {prep_path, cat_path, idx_path, core_path, Path(__file__).resolve()}
    checks = []
    def check(name, result):
        checks.append({'name': name, 'pass': bool(result)})
        assert result, name
    check('Eleven mechanical procedures and three literal post-push receipts', len(P) == len(selected) == 11 and {p['spellId'] for p in P} == set(selected) and len(deferred) == 3)
    check('Catalog remains848 with412 reviewed and436 pending', len(catalog) == 848 and idx['authoredCounts'] == {'reviewed': 412, 'pending': 436})
    check('Actual Wizard11 RP maximum40', core['caster_pools']['Wizard'][10] == 40)
    records = []
    for p in P:
        sid = p['spellId']; s = selected[sid]; f = catalog[sid]
        digest = sha256(json.dumps(f, ensure_ascii=False, sort_keys=True, separators=(',', ':')).encode()).hexdigest()
        check(sid + ' complete original source/access retained', f == s['fullSourceAndCurrentAccessRecord'] and digest == s['recordSha256'])
        check(sid + ' no ordinary spell promotion', f['operational'] is None and entries[sid]['authoredStatus'] == 'pending-authored-procedure')
        check(sid + ' actual rank6/base13 access retained', all(a['rank'] == 6 and a['baseRpCost'] == 13 for a in f['classAccess'].values()))
        check(sid + ' complete proposed procedure/two examples/new choices', len(p['procedure']) > 1900 and len(p['workedCases']) == 2 and all(len(c) > 280 for c in p['workedCases']) and p['newChoices'].startswith('NEW'))
        for e in f['source']['coreEntries'] + f['source']['possibleHistoricalAliases']:
            check(sid + ' complete Core source at ' + str(e['index']), core['spells'][e['index']] == e['original'])
        record = {**p, 'questionId': s['questionId'], 'originalQuestion': s['individualQuestion'], 'fullSourceAndCurrentAccessRecord': f,
                  'sourceRecordSha256': digest, 'status': 'unadopted-unsent-operating-proposal', 'examplesAreRuntimeTests': False}
        records.append(record)
    check('Twelve exact mechanical Core entries preserved', sum(len(catalog[p['spellId']]['source']['coreEntries']) for p in P) == 12)
    check('Guards and Wards both actual school placements preserved', {e['original']['school'] for e in catalog['guards-and-wards']['source']['coreEntries']} == {'Abjuration', 'Universal'})
    check('Globe printed Tier5 terminology remains intact', 'Tier 5' in catalog['globe-of-invulnerability']['source']['coreEntries'][0]['original']['effect'])
    check('Warp Field retains range10feet', catalog['elemental-warp-field']['source']['coreEntries'][0]['original']['range'] == '10 feet')
    for d in deferred:
        sid = d['spellId']; f = catalog[sid]
        check(sid + ' literal deferred source unchanged', f == d['fullSourceAndCurrentAccessRecord'] and f['operational'] is None and sid not in {r['spellId'] for r in records})
        for e in f['source']['coreEntries']:
            check(sid + ' full literal Core receipt at ' + str(e['index']), core['spells'][e['index']] == e['original'])
    check('Alignment Nexus distinct rank6 and rank8 preserved', {e['original']['level'] for e in catalog['alignment-nexus']['source']['coreEntries']} == {6, 8})
    cids = sorted({x['id'] for x in prep['completeCounterparts']} | {'greater-dispel', 'antimagic-field-lesser', 'fabricate', 'resonance-anchor', 'arcane-lock'})
    counterparts = []
    for sid in cids:
        e = entries[sid]; p = cat_path.parent / e['procedureFile']; d = read(p); inputs.add(p)
        for key in e['wholeCardPointer'].strip('/').split('/'):
            d = d[int(key)] if isinstance(d, list) else d[key]
        check(sid + ' whole current counterpart identity', d.get('id', d.get('spellId')) == sid)
        op = d.get('operational', d.get('operationalCandidate'))
        check(sid + ' actual current reviewed/pending status', (e['authoredStatus'] == 'reviewed-authored-operational-playtest' and isinstance(op, dict)) or (e['authoredStatus'] == 'pending-authored-procedure' and d.get('operational') is None))
        counterparts.append({'id': sid, 'completePreparedComparisonOccurrences': [x for x in prep['completeCounterparts'] if x['id'] == sid],
                             'currentSourceCatalogRecord': catalog[sid], 'currentAuthoredIndexEntry': e, 'completeCurrentAuthoredRecord': d})
    pending = {sid for sid in cids if entries[sid]['authoredStatus'] == 'pending-authored-procedure'}
    check('Sixteen whole current counterparts: eight reviewed/eight pending', len(counterparts) == 16 and len(pending) == 8)
    earlier = []
