    data = {'status': SHARED['status'], 'createdAtUtc': now, 'sharedProposal': SHARED, 'records': records, 'explicitJointIssues': ISSUES,
            'completeCurrentCounterparts': counterparts, 'earlierUnadoptedCounterpartProposals': earlier, 'completeClassComparisons': classes,
            'preservedTextualClassComparisons': prep['classComparisonRecords'], 'currentGoverningDocuments': guides, 'completeOriginalPreparations': [prep],
            'completeUntouchedDeferredReceipts': deferred, 'originalBookBindings': prep['currentBookBindings'], 'reviewedExpeditionStatus': status,
            'sourceFiles': source_info, 'runtimeImplemented': False, 'cosmologyReviewed': False, 'sourceInformationDeleted': 0, 'pushed': False}
